// ─────────────────────────────────────────────────────────────────────────────
// SEED FUNCTION — ensures extra categories exist, inserts all 560 books
// ─────────────────────────────────────────────────────────────────────────────
export async function seedAcademicBooks() {
  try {
    // 1. Ensure extra categories (IT, CHEM, MATH, GEN) are present
    for (const cat of EXTRA_CATEGORIES) {
      await db.run(
        'INSERT OR IGNORE INTO categories (name, code, description) VALUES (?, ?, ?)',
        [cat.name, cat.code, cat.description]
      );
    }

    // 2. Fetch all category codes → IDs
    const cats = await db.query('SELECT id, code FROM categories');
    const catMap = {};
    cats.forEach(c => { catMap[c.code] = c.id; });

    // 3. Insert books (INSERT OR IGNORE prevents duplicates on repeated runs)
    let inserted = 0;
    let skipped = 0;
    for (const book of BOOKS) {
      const catId = catMap[book.c];
      if (!catId) { skipped++; continue; }
      const copies = book.cop || 3;
      try {
        const result = await db.run(
          `INSERT OR IGNORE INTO books
            (title, author, isbn, category_id, price, description, total_copies, available_copies, shelf_location, cover_image, status)
           VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'active')`,
          [
            book.t,
            book.a,
            book.isbn,
            catId,
            book.p || 450,
            book.d || `${book.t} — recommended textbook for B.Tech ${book.c} curriculum.`,
            copies,
            copies,
            book.sh,
            copies > 4 ? COVER : copies > 2 ? COVER2 : COVER3
          ]
        );
        if (result.changes > 0) inserted++;
        else skipped++;
      } catch (err) {
        // Ignore ISBN duplicate conflicts
        skipped++;
      }
    }

    console.log(`📚 Academic Book Catalog: ${inserted} new books inserted, ${skipped} skipped (already exist).`);
    console.log(`   Total catalog size check: see /api/admin/books for full inventory.`);
    return { inserted, skipped };
  } catch (err) {
    console.error('❌ seedAcademicBooks error:', err.message);
    throw err;
  }
}
